}

output "endpoint" {
  value = module.database.endpoint
}

output "hosted_zone_id" {
  value = module.database.hosted_zone_id
}

output "id" {
  value = module.database.id
}

output "name" {
  value = module.database.name
}

output "port" {
  value = module.database.port
}

output "resource_id" {
  value = module.database.resource_id
}

output "status" {
  value = module.database.status
}

output "kms_arns" {
  value = one(module.database_kms[*].key_arns[local.kms_key_name])
}

output "kms_key_ids" {
  value = one(module.database_kms[*].key_ids[local.kms_key_name])
}

output "kms_replica_arn" {
  value = one(aws_kms_replica_key.replica_key[*].arn)
}

output "kms_replica_id" {
  value = one(aws_kms_replica_key.replica_key[*].key_id)
}

output "vault_secret_path" {
  value = vault_generic_secret.admin_credentials.path
}
```

Then verify:
```bash
cd /Users/steve.briggs/projects/operations/terraform/iac-library/aws/storage/database-tools-db
terraform fmt -check output.tf
```

Run `terraform fmt output.tf` to fix diffs if needed.

End with `STATUS: DONE` or `STATUS: BLOCKED`.

